#include <iostream>
#include <cctype>

void inspect(char ch) {
    unsigned char uc = static_cast<unsigned char>(ch);
    std::cout << "Char: '" << ch << "' | "
              << "isspace: " << (std::isspace(uc) ? 1 : 0) << " | "
              << "iscntrl: " << (std::iscntrl(uc) ? 1 : 0) << " | "
              << "ispunct: " << (std::ispunct(uc) ? 1 : 0) << " | "
              << "isprint: " << (std::isprint(uc) ? 1 : 0) << " | "
              << "isgraph: " << (std::isgraph(uc) ? 1 : 0) << "\n";
}

int main() {
    inspect(' ');
    inspect('\n');
    inspect(';');
    inspect('Q');
    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    const char source[] = "Happy Birthday to You";
    char bufferCopy[25];
    char bufferTrunc[15];

    // 1. Copying using strcpy and strncpy
    std::strcpy(bufferCopy, source);
    std::strncpy(bufferTrunc, source, sizeof(bufferTrunc) - 1);
    bufferTrunc[sizeof(bufferTrunc) - 1] = '\0'; // Explicit termination

    std::cout << "strcpy result: " << bufferCopy << "\n";
    std::cout << "strncpy result: " << bufferTrunc << "\n";

    // 2. Concatenation using strcat and strncat
    char greeting[30] = "Happy ";
    const char target[] = "New Year 2026";
    std::strcat(greeting, "Holidays");
    std::cout << "strcat result: " << greeting << "\n";

    char customMsg[40] = "Welcome: ";
    std::strncat(customMsg, target, 8); // appends "New Year" + '\0'
    std::cout << "strncat result: " << customMsg << "\n";

    return 0;
}

#include <iostream>
#include <cstring>
#include <string_view>

int main() {
    const char* s1 = "Happy New Year";
    const char* s2 = "Happy New Year";
    const char* s3 = "Happy Holidays";

    // Testing strcmp
    std::cout << "strcmp(s1, s2) == 0: " << (std::strcmp(s1, s2) == 0 ? "true" : "false") << "\n";
    std::cout << "strcmp(s1, s3): " << (std::strcmp(s1, s3) > 0 ? "> 0" : "<= 0") << "\n";
    std::cout << "strcmp(s3, s1): " << (std::strcmp(s3, s1) < 0 ? "< 0" : ">= 0") << "\n";

    // Testing strncmp with prefix length
    std::cout << "strncmp(s1, s3, 6): " << std::strncmp(s1, s3, 6) << " (matching 'Happy ')\n";
    std::cout << "strncmp(s1, s3, 7): " << (std::strncmp(s1, s3, 7) > 0 ? "> 0" : "<= 0") << "\n";

    // Modern C++17 comparison with string_view
    std::string_view sv1{s1};
    std::string_view sv3{s3};
    std::cout << "C++17 string_view (sv1 == sv3): " << std::boolalpha << (sv1 == sv3) << "\n";

    return 0;
}
